  header {
    position:sticky; top:0; z-index:50;
    background:rgba(0,0,0,0.85);
    backdrop-filter:blur(8px);
    border-bottom:1px solid rgba(255,255,255,0.08);
  }
  .header-inner {
    max-width:1200px; margin:0 auto; padding:20px;
    display:flex; align-items:center; justify-content:space-between;
  }
  .logo { font-family:'Anton'; font-size:22px; text-transform:uppercase; color:#fff; letter-spacing:0.02em; }
  nav ul { display:flex; gap:32px; list-style:none; }
  nav a { font-size:14px; font-weight:500; color:rgba(255,255,255,0.7); }
  nav a:hover { color:#fff; }

  /* Back link */
  .back-link {
    padding:32px 0 0;
  }
  .back-link a {
    font-size:14px; font-weight:500; color:rgba(255,255,255,0.5);
  }
  .back-link a:hover { color:rgba(255,255,255,0.8); }

  /* Hero */
  .act-hero {
    padding:32px 0 80px;
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:64px;
    align-items:center;
  }
  .act-image {
    position:relative;
    width:100%;
    aspect-ratio:4/3;
    border-radius:1.5rem;
    background:
      radial-gradient(ellipse 60% 60% at 30% 20%, rgba(254,49,132,0.25) 0%, transparent 60%),
      radial-gradient(ellipse 60% 60% at 80% 80%, rgba(236,114,17,0.2) 0%, transparent 60%),
      linear-gradient(180deg, #1a1a1a 0%, #0d0d0d 100%);
    border:1px solid rgba(255,255,255,0.08);
    display:flex; align-items:center; justify-content:center;
  }
  .act-image span {
    font-size:12px; font-weight:600; letter-spacing:0.1em; text-transform:uppercase;
    color:rgba(255,255,255,0.35);
  }

  .section-label {
    font-size:14px; font-weight:400; letter-spacing:0.1em; text-transform:uppercase;
    color:#FE3184; margin-bottom:16px; display:block;
  }
  .act-title { font-size:48px; line-height:1.05; letter-spacing:-0.01em; margin-bottom:20px; }
  .act-desc { font-size:18px; color:rgba(255,255,255,0.6); margin-bottom:24px; max-width:480px; }

  .meta-row {
    display:flex; gap:24px; margin-bottom:20px; flex-wrap:wrap;
  }
  .meta-item {
    font-size:13px; font-weight:600; letter-spacing:0.04em; color:rgba(255,255,255,0.5);
    display:flex; align-items:center; gap:6px;
  }
  .meta-item strong { color:rgba(255,255,255,0.85); font-weight:600; }

  .attribution {
    font-size:13px; color:rgba(255,255,255,0.4); margin-bottom:32px; font-style:normal;
  }

  .cta-row { display:flex; gap:16px; flex-wrap:wrap; }
  .btn-primary {
    background:linear-gradient(135deg, #FE3184 0%, #FF6B35 50%, #ec7211 100%);
    color:#fff; font-weight:600; font-size:16px;
    padding:16px 32px; border-radius:9999px; border:none;
    box-shadow:0 10px 40px rgba(254,49,132,0.3);
    transition:transform 0.3s, box-shadow 0.3s;
    cursor:pointer; display:inline-block;
  }
  .btn-primary:hover { transform:translateY(-2px); box-shadow:0 15px 50px rgba(254,49,132,0.4); }
  .btn-secondary {
    background:transparent; color:#fff; font-weight:600; font-size:16px;
    padding:16px 32px; border-radius:9999px; border:1px solid rgba(255,255,255,0.2);
    transition:background 0.3s, border-color 0.3s; cursor:pointer; display:inline-block;
  }
  .btn-secondary:hover { background:rgba(255,255,255,0.05); border-color:rgba(255,255,255,0.4); }

