  .tracker-section { padding:64px 0; border-top:1px solid rgba(255,255,255,0.08); }
  .tracker-title { font-size:32px; margin-bottom:40px; text-align:center; }
  .tracker {
    display:flex; justify-content:space-between; position:relative;
    max-width:900px; margin:0 auto;
  }
  .tracker::before {
    content:''; position:absolute; top:20px; left:0; right:0; height:2px;
    background:rgba(255,255,255,0.1); z-index:0;
  }
  .track-step {
    position:relative; z-index:1; display:flex; flex-direction:column; align-items:center;
    gap:12px; flex:1;
  }
  .track-dot {
    width:40px; height:40px; border-radius:50%;
    display:flex; align-items:center; justify-content:center;
    font-size:13px; font-weight:700;
    background:#0d0d0d; border:2px solid rgba(255,255,255,0.15);
    color:rgba(255,255,255,0.4);
  }
  .track-step.done .track-dot {
    background:linear-gradient(135deg, #FE3184 0%, #ec7211 100%);
    border-color:transparent; color:#fff;
  }
  .track-step.current .track-dot {
    border-color:#FE3184; color:#FE3184;
    box-shadow:0 0 20px rgba(254,49,132,0.4);
  }
  .track-label { font-size:12px; font-weight:600; letter-spacing:0.05em; text-transform:uppercase; color:rgba(255,255,255,0.5); text-align:center; }
  .track-step.current .track-label, .track-step.done .track-label { color:rgba(255,255,255,0.85); }

