    width:56px; height:56px; border-radius:12px;
    background:rgba(254,49,132,0.1); border:1px solid rgba(254,49,132,0.2);
    display:flex; align-items:center; justify-content:center;
  }
  .icon-box svg { width:24px; height:24px; stroke:#FE3184; stroke-width:1.5; fill:none; }
  .partner-card h3 { font-size:20px; color:#fff; font-weight:600; margin-bottom:8px; font-family:'Inter'; }
  .partner-card p { font-size:15px; color:rgba(255,255,255,0.55); margin-bottom:12px; }
  .partner-card .privacy-note { font-size:13px; color:rgba(255,255,255,0.4); }

  /* What you'll see after */
  .after-section { padding:64px 0; border-top:1px solid rgba(255,255,255,0.08); }
  .after-grid {
    display:grid; grid-template-columns:repeat(3, 1fr); gap:24px; margin-top:40px;
  }
  .after-item {
    padding:28px;
    border:1px solid rgba(255,255,255,0.08); border-radius:1rem;
    background:linear-gradient(180deg, #1a1a1a 0%, #0d0d0d 100%);
  }
  .after-item .num { font-family:'Anton'; font-size:28px; color:#FE3184; margin-bottom:12px; }
  .after-item p { font-size:15px; color:rgba(255,255,255,0.6); }

