  .act-card {
    position:relative; overflow:hidden;
    background:linear-gradient(180deg, #1a1a1a 0%, #0d0d0d 100%);
    border:1px solid rgba(255,255,255,0.08); border-radius:1rem;
    padding:28px; transition:transform 0.5s, border-color 0.5s, box-shadow 0.5s;
    cursor:pointer;
  }
  .act-card::before {
    content:''; position:absolute; top:-80px; left:-80px; width:160px; height:160px;
    border-radius:50%; filter:blur(48px); opacity:0;
    background:linear-gradient(135deg, rgba(254,49,132,0.4), rgba(236,114,17,0.3));
    transition:opacity 0.7s;
  }
  .act-card::after {
    content:''; position:absolute; bottom:0; left:50%; transform:translateX(-50%) scaleX(0);
    width:100%; height:4px;
    background:linear-gradient(90deg, #FE3184 0%, #FF6B35 50%, #ec7211 100%);
    transition:transform 0.5s;
  }
  .act-card:hover { transform:translateY(-8px); border-color:rgba(255,255,255,0.15); box-shadow:0 20px 60px rgba(0,0,0,0.4), 0 0 80px rgba(254,49,132,0.1); }
  .act-card:hover::before { opacity:1; }
  .act-card:hover::after { transform:translateX(-50%) scaleX(1); }
  .card-badge {
    display:inline-block; font-size:11px; font-weight:600; letter-spacing:0.08em; text-transform:uppercase;
    color:#FE3184; background:rgba(254,49,132,0.1); border:1px solid rgba(254,49,132,0.2);
    padding:5px 12px; border-radius:9999px; margin-bottom:16px; position:relative; z-index:1;
  }
  .act-card h4 { font-family:'Inter'; font-size:18px; font-weight:600; color:rgba(255,255,255,0.85); margin-bottom:8px; position:relative; z-index:1; transition:color 0.3s; }
  .act-card:hover h4 { color:#fff; }
  .act-card p { font-size:14px; color:rgba(255,255,255,0.5); margin-bottom:20px; position:relative; z-index:1; transition:color 0.3s; }
  .act-card:hover p { color:rgba(255,255,255,0.7); }
  .card-link { font-size:14px; font-weight:600; color:#fff; position:relative; z-index:1; }

  /* Footer */
  footer { border-top:1px solid rgba(255,255,255,0.08); padding:48px 0; }
  .footer-inner { display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:16px; }
  .footer-inner nav ul { gap:24px; }
  .footer-inner p { font-size:13px; color:rgba(255,255,255,0.4); }

