  @media (max-width:768px) {
    nav ul { display:none; }
    .act-hero { grid-template-columns:1fr; gap:32px; padding-bottom:56px; }
    .act-title { font-size:34px; }
    .tracker { flex-direction:column; gap:24px; align-items:flex-start; }
    .tracker::before { display:none; }
    .track-step { flex-direction:row; align-items:center; }
    .partner-card { grid-template-columns:1fr; }
    .after-grid, .related-grid { grid-template-columns:1fr; }
    .cta-row .btn-primary, .cta-row .btn-secondary { width:100%; text-align:center; }
    .footer-inner { flex-direction:column; align-items:flex-start; }
  }
</style>
</head>
